/* Account/access workflow study. Synthetic identities/configuration only; never starts OAuth or native writes. */
(function(){
'use strict';
let flow=null,context=null;
const access={overrides:false,client:'',agent:'',redirect:'',giphy:'',pendingRestart:false};
function el(tag,cls,text){const node=document.createElement(tag);if(cls)node.className=cls;if(text!==undefined)node.textContent=text;return node}
function name(account){return account==='guest'?'Guest':'u/'+account}
function group(root,title){const section=el('section','settings-group');section.append(el('h3',null,title));const body=el('div','settings-rows utility-panel');section.append(body);root.append(section);return body}
function note(root,text){root.append(el('p','field-help',text))}
function button(root,title,action,id){const node=el('button','utility-button',title);node.type='button';if(id){node.id=id;node.dataset.category=id}node.addEventListener('click',action);root.append(node);return node}
function init(account){if(!flow){const fresh=new URLSearchParams(location.search).get('accounts')==='new';flow={active:fresh?'guest':account,entry:account,profiles:fresh?[]:[{id:'secondreader',complete:true},{id:'weekendreader',complete:true}],guestKnown:!fresh,setupTarget:null,method:'webview'};const scenario=new URLSearchParams(location.search).get('api-state');access.overrides=['missing','custom'].includes(scenario);if(scenario==='custom')access.client='X'.repeat(22);
 if(!fresh){window.RelaxeOnboarding?.ensureExisting('weekendreader',{layout:'large',theme:'dark',folder:'/Downloads/Relaxe · example folder'});window.RelaxeOnboarding?.ensureExisting('secondreader',{layout:'gallery',theme:'light',folder:''});window.RelaxeOnboarding?.ensureExisting('guest',{layout:'compact',theme:'system',folder:''});}}
 else if(flow.entry!==account){flow.entry=account;flow.active=account==='guest'||flow.profiles.some(p=>p.id===account)?account:'guest'}
}
function refresh(){const {root}=context;root.replaceChildren();draw()}
function say(text){const status=context.root.querySelector('#account-workflow-feedback');if(status)status.textContent=text;else context.announce(text)}
function modal(title,build,locked=false){const origin=document.activeElement,dialog=el('dialog','utility-modal');dialog.id='account-workflow-modal';const heading=el('h3',null,title);heading.id='account-workflow-modal-title';dialog.setAttribute('aria-labelledby',heading.id);const body=el('div','filter-modal-body'),actions=el('div','dialog-actions');dialog.append(heading,body,actions);context.root.append(dialog);const close=()=>{dialog.close();dialog.remove();if(origin?.isConnected)origin.focus({preventScroll:true})};if(!locked)button(actions,'Cancel',close).autofocus=true;dialog.addEventListener('cancel',event=>{event.preventDefault();if(!locked)close()});dialog.addEventListener('keydown',event=>{if(event.key==='Escape')event.stopPropagation()});build({body,actions,close});dialog.showModal()}
function ready(account){flow.active=account;const profile=flow.profiles.find(p=>p.id===account),needsSetup=account==='guest'?!flow.guestKnown:!profile?.complete;if(needsSetup){flow.setupTarget=account;context.navigate('accounts-setup','accounts-new-setup')}else context.navigate('accounts-ready','accounts-ready')}
function remove(account){const active=account===flow.active;modal(active?'Log out of '+name(account)+'?':'Remove '+name(account)+' from this device?',({body,actions,close})=>{note(body,'Remove this device’s saved sign-in and resume data for '+name(account)+'. Related local records may also be cleared. This does not delete the Reddit account.');if(active)note(body,'You will return to Guest. Use Guest instead if you want to keep this account signed in.');button(actions,active?'Log out':'Remove account',()=>{flow.profiles=flow.profiles.filter(p=>p.id!==account);if(active)flow.active='guest';close();refresh();say('Removed from this account-workflow fixture only. No native account, token, local data or Reddit account was changed.');});})}
function options(account){modal(name(account),({body,actions,close})=>{note(body,account===flow.active?'Current account':'Saved sign-in on this device');button(body,'Review account setup',()=>{flow.setupTarget=account;close();context.navigate('accounts-setup','accounts-review-setup')});button(body,account===flow.active?'Log out':'Remove from this device',()=>{close();remove(account)});})}
function beginLogin(){if(access.overrides&&!access.client){say('Set a custom Client ID in API Keys before adding an account while overrides are enabled.');return}context.navigate('account-login','accounts-add')}
function login(){if(access.overrides&&!access.client){say('Set a custom Client ID in API Keys before continuing with overrides enabled.');return}const browser=document.getElementById('settings-login-browser').value;if(flow.method!=='webview'&&browser==='none'){say('This browser method is unavailable. Use the in-app sign-in method.');return}const effective=flow.method==='auth-tab'&&browser==='chrome'?'webview':flow.method;
 const launch=()=>modal('Reddit sign-in route',({body,actions,close})=>{note(body,'The native '+({'webview':'in-app Reddit page','chrome':'Chrome Custom Tab','auth-tab':'Auth Tab'})[effective]+' handles Reddit sign-in. This study opens no Reddit page and collects no password, token or authorization code.');if(effective!==flow.method)note(body,'The selected Auth Tab is unsupported here; the existing fallback is the in-app sign-in page.');button(actions,'Preview sign-in return',()=>{close();const result=new URLSearchParams(location.search).get('login-result')||'new';const errors={cancel:'Sign-in cancelled.',denied:'Reddit authorization was denied.',network:'Could not connect while signing in.',unauthorized:'Reddit rejected the client configuration.',rate:'Reddit rate-limited sign-in. Try again later.',server:'Reddit could not complete sign-in.',state:'The sign-in response could not be verified.',profile:'Could not load the signed-in account.',webview:'The system WebView could not open.'};if(errors[result]){say(errors[result]+' Existing accounts and setup choices are kept in this fixture. Retry explicitly or choose another available method.');return}if(!['new','returning'].includes(result)){say('Unknown sign-in result. No account changed in this fixture.');return}const account=result==='returning'?'secondreader':'newreader';if(!flow.profiles.some(p=>p.id===account))flow.profiles.push({id:account,complete:result==='returning'||!!window.RelaxeOnboarding?.isComplete(account)});ready(account);});});
 if(flow.method==='auth-tab')modal('Review before signing in',({body,actions,close})=>{note(body,'Review the Reddit User Agreement and Relaxe for Reddit Privacy Policy before continuing. The app policy remains a draft in this study; acknowledging here submits no real agreement.');for(const [title,href]of [['Reddit User Agreement','https://redditinc.com/policies/user-agreement'],['Relaxe for Reddit Privacy Policy · draft','settings.html?rev=137&page=privacy&focus=1']]){const link=el('a','account-policy-link',title);link.href=href;link.target='_blank';link.rel='noopener noreferrer';body.append(link)}button(actions,'Do not agree',()=>{close();context.goBack();context.announce('Sign-in was not started.');}).autofocus=true;button(actions,'Agree · preview',()=>{close();launch()});},true);else launch();
}
function editAccess(key,title){modal(title+' · example configuration',({body,actions,close})=>{note(body,'Use examples only in this design study. Nothing is sent to Reddit or written to Android.');const wrap=el('div','filter-field'),label=el('label',null,title),input=el('input','utility-input');label.htmlFor='api-example-value';input.id=label.htmlFor;input.type='text';input.autocomplete='off';input.value=access[key];wrap.append(label,input);body.append(wrap);const feedback=el('p','field-help');feedback.setAttribute('role','status');body.append(feedback);if(key==='client')button(body,'Insert example Client ID',()=>{input.value='X'.repeat(22);validate()});if(key==='giphy')button(body,'Insert example Giphy key',()=>{input.value='Y'.repeat(32);validate()});if(key==='client')button(body,'Scan QR code',()=>{feedback.textContent='Existing native QR/camera route. No camera is opened in this study.'});
 const apply=button(actions,'Apply example',()=>{const value=key==='agent'?input.value.trim():['client','redirect'].includes(key)?input.value.replace(/\s/g,''):input.value;access[key]=value;if(key!=='giphy')access.pendingRestart=true;close();refresh();say('Example configuration saved in page memory only. No native key or access mechanism changed.');});function validate(){const value=key==='client'?input.value.replace(/\s/g,''):input.value;const valid=key==='client'?value.length===22:key==='giphy'?value.length===0||value.length===32:true;apply.disabled=!valid;input.setAttribute('aria-invalid',String(!valid&&value!==''));feedback.textContent=valid?'':key==='client'?'Client ID must contain 22 characters after whitespace removal.':'Giphy key must contain 32 characters, or be empty to use its default.';}input.addEventListener('input',validate);validate();})}
function draw(){const {root,view,navigate}=context;
 if(view==='accounts'){
  if(new URLSearchParams(location.search).get('account-lock')==='on'&&!context.unlocked){const panel=group(root,'Unlock accounts');note(panel,'Use the existing device-authentication route before account names are shown. No biometric or credential is collected here.');if(document.getElementById('settings-auth').value==='unavailable'){note(panel,'Device authentication is unavailable.');button(panel,'Back',context.goBack);}else button(panel,'Authenticate',()=>{const result=new URLSearchParams(location.search).get('auth-result');if(['cancel','error'].includes(result)){context.goBack();return}context.unlocked=true;refresh();(context.root.querySelector('#accounts-current-options')||context.root.querySelector('#accounts-add'))?.focus({preventScroll:true})});return}
  const current=group(root,'Current account');current.append(el('strong',null,name(flow.active)));if(flow.active!=='guest')button(current,'Account options',()=>options(flow.active),'accounts-current-options');else note(current,'Browsing mode. Saved local data is separate from signed-in accounts.');
  const others=group(root,'Other accounts');const list=flow.profiles.filter(p=>p.id!==flow.active).sort((a,b)=>a.id.localeCompare(b.id));if(!list.length)note(others,'No other saved sign-ins.');for(const profile of list){const row=el('div','filter-item');row.append(el('strong',null,name(profile.id)));const actions=el('div','filter-actions');button(actions,'Switch',()=>ready(profile.id)).setAttribute('aria-label','Switch to '+name(profile.id));button(actions,'Options',()=>options(profile.id)).setAttribute('aria-label','Options for '+name(profile.id));row.append(actions);others.append(row)}
  const actions=group(root,'Account actions');button(actions,'Add account',beginLogin,'accounts-add');button(actions,'API Keys',()=>navigate('api-access','accounts-api'),'accounts-api');const guest=button(actions,'Use Guest',()=>ready('guest'),'accounts-guest');guest.disabled=flow.active==='guest'&&flow.guestKnown;note(actions,'Use Guest keeps saved sign-ins and their places. Log out removes a saved sign-in from this device.');
 }
 if(view==='account-login'){
  const panel=group(root,'Sign in to Reddit');note(panel,'Reddit handles your credentials through the existing native sign-in route. The selected account is changed only after account information is successfully loaded.');const label=el('label',null,'Sign-in method'),select=el('select','utility-input');select.id='login-method';label.htmlFor=select.id;panel.append(label,select);const browser=document.getElementById('settings-login-browser').value;for(const [value,title]of [['webview','In-app Reddit sign-in'],['chrome','Chrome Custom Tab'],['auth-tab','Auth Tab']]){const option=el('option',null,title);option.value=value;option.disabled=value!=='webview'&&browser==='none';select.append(option)}select.value=flow.method;select.addEventListener('change',()=>{flow.method=select.value});button(panel,'Continue to Reddit',login,'login-continue');button(panel,'API Keys',()=>navigate('api-access','login-api'),'login-api');note(panel,'Default method matches the current native entry. Browser capability and OAuth checks remain native; unsupported Auth Tab retains the existing fallback.');
 }
 if(view==='api-access'){
  const panel=group(root,'Reddit API configuration');const row=el('div','video-setting'),label=el('span',null,'Enable custom API configuration'),input=el('button','video-toggle');input.id='api-overrides';label.id='api-overrides-label';input.type='button';input.setAttribute('role','switch');input.setAttribute('aria-labelledby',label.id);input.setAttribute('aria-checked',String(access.overrides));row.append(label,input);panel.append(row);input.addEventListener('click',()=>{access.overrides=!access.overrides;refresh()});note(panel,'Off uses the existing built-in configuration. On uses the supported custom configuration. These settings apply across accounts.');
  for(const [key,title]of [['client','Client ID'],['agent','User agent'],['redirect','Redirect URI']]){const row=el('div','utility-action');row.append(el('strong',null,title),el('small',null,access[key]?'Example configured':'Built-in/default value'));const edit=button(row,'Edit',()=>editAccess(key,title),'api-edit-'+key);edit.disabled=!access.overrides;edit.setAttribute('aria-label','Edit '+title);panel.append(row)}const media=group(root,'Giphy');note(media,'Independent of the Reddit override switch.');button(media,'Edit Giphy API key',()=>editAccess('giphy','Giphy API key'),'api-edit-giphy');if(access.pendingRestart)root.append(el('p','compose-notice','Native app restarts when leaving after restart-required API edits. This preview does not restart.'));note(root,'No built-in keys are displayed. The native Client ID, redirect, scope, QR scan, validation and deferred-restart mechanisms remain unchanged.');
 }
 if(view==='accounts-ready'){const panel=group(root,name(flow.active)+' is ready');note(panel,'This is a synthetic account-workflow result. No actual sign-in, switch or account data change occurred.');button(panel,'Start browsing',()=>context.announce('Existing reader/account-restoration route for '+name(flow.active)+'. No native reader is opened.'),'accounts-browse');button(panel,'Review account setup',()=>{flow.setupTarget=flow.active;navigate('accounts-setup','accounts-review-setup')},'accounts-review-setup');button(panel,'Accounts',()=>navigate('accounts','accounts-ready-list'));}
 const feedback=el('p','field-help');feedback.id='account-workflow-feedback';feedback.setAttribute('role','status');root.append(feedback);
 if(view==='accounts'&&access.overrides&&!access.client)say('Custom API overrides are enabled without a custom Client ID. Open API Keys before adding an account.');
}
window.RelaxeAccounts={render(root,account,view,navigate,announce,goBack){init(account);context={root,view,navigate,announce,goBack,unlocked:false};draw()},setupAccount(account='guest'){if(!flow)init(account);return flow.setupTarget||flow.active},finishSetup(account){if(account==='guest')flow.guestKnown=true;else{const profile=flow.profiles.find(p=>p.id===account);if(profile)profile.complete=true}flow.active=account;flow.setupTarget=null},activeAccount(){return flow?.active||'guest'}};
})();
